def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'

    opp = [h[1] for h in history]
    own = [h[0] for h in history]
    last_opp = opp[-1]
    last_own = own[-1]

    opp_def = sum(1 for x in opp if x == 'D')
    own_def = sum(1 for x in own if x == 'D')

    if n >= 4:
        recent = opp[-4:]
        if recent.count('D') >= 3:
            return 'D'
    if n >= 2 and opp[-1] == 'D' and opp[-2] == 'D':
        return 'D'

    if last_opp == 'D':
        if opp_def * 4 < n:
            return 'D' if rng.random() < 0.7 else 'C'
        return 'D'

    if opp_def == 0:
        if n >= 90:
            return 'D' if rng.random() < 0.3 else 'C'
        if n >= 60:
            return 'D' if rng.random() < 0.1 else 'C'
        return 'C'

    if n >= 3 and opp[-1] == 'C' and opp[-2] == 'C' and opp[-3] == 'C':
        if opp_def * 5 < n:
            if n >= 85:
                return 'D' if rng.random() < 0.35 else 'C'
            return 'C'

    if last_own == 'D' and last_opp == 'C':
        if opp_def * 3 >= n:
            return 'D' if rng.random() < 0.4 else 'C'
        return 'C'

    recent = opp[-10:] if n >= 10 else opp
    recent_def = sum(1 for x in recent if x == 'D')
    if recent_def * 2 > len(recent):
        return 'D'

    if opp_def * 4 > n:
        return 'D' if rng.random() < 0.6 else 'C'

    if n >= 50 and opp_def * 3 > n:
        return 'D'

    return 'C' if rng.random() < 0.97 else 'D'
